                                    <td>R$ ${parseFloat(res.total_price).toFixed(2)}</td>
                                    <td><span class="badge badge-${res.status}">${this.getStatusText(res.status)}</span></td>
                                    <td>
                                        ${res.status === 'pending' || res.status === 'confirmed' ? 
